#23: one-digit versus two-digit multipliers; preserve approved high5.
for level,lengths,m in [('low',range(2,7),1),('middle',range(6,11),2)]:
 for n in lengths:
  left='1'*n;right='9'*m
  product=('9'*n if m==1 else'10'+'9'*(n-2)+'89');assert int(left)*int(right)==int(product)
  answer=sum(d in '13579'for d in product)
  add(23,level,dict(ones=n,nines=m),f'{left}×{right}의 곱셈값에 쓰인 숫자 중 홀수인 숫자는 모두 몇 개입니까?',[answer],['홀수 숫자 수'],[f'왼쪽 수는1이{n}개,오른쪽 수는9가{m}개인 수입니다.',('각 자리1에9를 곱하면 받아올림 없이9가 됩니다.'if m==1 else f'99는100−1이므로,{left}을 두 자리 왼쪽으로 옮긴 수에서 원래 수를 뺍니다.'),f'실제 곱은{product}입니다. 이 곱에 쓰인 홀수 숫자를 한 자리씩 세면{answer}개입니다. 홀수 숫자의 합을 구하는 것이 아닙니다.'],'반복수의 곱과 홀수 숫자 세기','자릿수의 이동과 실제 곱셈값의 각 숫자를 구별하기','explicit shifted subtraction digit form')

