def clue_text(c):
 a,b=[selector(s)for s in c['s']]
 if c['op']=='eq':return a+'과 '+b+'은 같은 보관함입니다.'
 if c['op']=='ne':return a+'과 '+b+'은 서로 다른 보관함입니다.'
 if c['d']<0:a,b=b,a
 return f'{a}의 번호는 {b}의 번호보다{abs(c["d"])} 큽니다.'
def node_label(i,n):
 if i<n:return BOXES[i]+' 보관함'
 t,v=divmod(i,n);return COLORS[v]+' 표식의 보관함'if t==1 else OBJECTS[v]+'이 든 보관함'
