 steps=[f'번호는1~{n}을 한 번씩 쓰고,각 표식'+('과 물건'if k==3 else'')+'도 한 번씩 대응합니다. 번호 차 단서는 가능한 번호의 범위를 줄이고,같은 번호를 두 보관함에 쓸 수 없다는 조건과 함께 적용합니다.']
 for start in range(0,len(events),3):
  group=events[start:start+3];why='·'.join(dict.fromkeys(v[0]for v in group));steps.append(why+'를 차례로 적용하면 '+', '.join(f'{name}은{value}번'for reason,name,value in group)+'으로 정해집니다.')
