 headers=['보관함','번호','표식']+(['내용물']if k==3 else[])
 add(24,level,dict(n=n,attributeCount=k,clues=case['clues']),text,answer,labels,steps,'보관함의 여러 속성 대응','번호 차와 일대일 대응 단서를 서로 연결해 모순을 없애기','finite permutation constraints plus transparent domain propagation',givenTable=dict(label='보관함의 실제 단서',headers=['단서'],rows=[[t]for t in clues]),responseTable=dict(label='답을 적는 대응표',headers=headers,rows=[[BOXES[i]]+['']*k for i in range(n)]),solutionTable=dict(label='보관함 정답 대응표',headers=headers,rows=rows))

